   132→    func (idx: *BTreeIndex) index_insert(key: i64, row_id: i64) -> i32 {
   133→        if idx.node_count >= MAX_NODES {
   134→            return IDX_ERR_FULL;
   135→        }
   136→
   137→        let leaf_idx = idx.find_leaf(key);
   138→        let leaf = idx.nodes[leaf_idx];
   139→
   140→        if leaf.key_count >= MAX_KEYS {
   141→            return IDX_ERR_FULL;  // 분할 미구현 (간단화)
   142→        }
   143→
   144→        // 삽입 위치 찾기
   145→        let pos = leaf.key_count;
   146→        let i = 0;
   147→        for i = 0; i < leaf.key_count; i = i + 1 {
   148→            if key < leaf.keys[i] {
   149→                pos = i;
   150→                break;
   151→            }
   152→        }
   153→
   154→        // 키 삽입 (오른쪽으로 시프트)
   155→        let j = leaf.key_count;
   156→        for j > pos {
   157→            leaf.keys[j] = leaf.keys[j - 1];
   158→            leaf.row_ids[j] = leaf.row_ids[j - 1];
   159→            j = j - 1;
   160→        }
   161→        leaf.keys[pos] = key;
   162→        leaf.row_ids[pos] = row_id;
   163→        leaf.key_count = leaf.key_count + 1;
   164→
   165→        idx.nodes[leaf_idx] = leaf;
   166→        idx.key_count = idx.key_count + 1;
   167→        return IDX_OK;
   168→    }
